const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const africa = ee.FeatureCollection('FAO/GAUL/2015/level0').filter(ee.Filter.eq('AD_NAME', 'Africa')).geometry();
    const scale = 5000; // Use a coarse scale for a continental analysis to avoid timeout

    // Define the two time periods
    const start1 = 2004;
    const end1 = 2007;
    const start2 = 2016;
    const end2 = 2019;

    // 2. Data Acquisition & Processing
    const dataset = ee.ImageCollection('MODIS/006/MCD12Q1').select('LC_Type1');

    // Function to create a binary mask for cropland
    // Class 12: Croplands, Class 14: Cropland/Natural Vegetation Mosaics
    const createCroplandMask = (image) => {
        return image.eq(12).or(image.eq(14));
    };

    // Function to calculate cropland area for a given year
    const calculateCroplandArea = (year) => {
        const image = dataset.filterDate(year + '-01-01', year + '-12-31').first();
        if (!image) return null; // Handle case where image might be missing
        const croplandMask = createCroplandMask(image);
        const areaImage = ee.Image.pixelArea().mask(croplandMask);
        const area = areaImage.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: africa,
            scale: scale,
            maxPixels: 1e12
        });
        return ee.Number(area.get('area'));
    };

    // 3. Calculation
    const area_start1 = calculateCroplandArea(start1);
    const area_end1 = calculateCroplandArea(end1);
    const area_start2 = calculateCroplandArea(start2);
    const area_end2 = calculateCroplandArea(end2);

    // Use ee.Algorithms.If to handle potential nulls before getting info
    const allImagesExist = ee.Number(ee.List([area_start1, area_end1, area_start2, area_end2]).reduce(ee.Reducer.min()));

    const result = ee.Algorithms.If(
        allImagesExist.gt(0),
        () => {
            const expansion1 = area_end1.subtract(area_start1);
            const expansion2 = area_end2.subtract(area_start2);
            // Rate is change over 3 years for both periods
            const rate1 = expansion1.divide(end1 - start1);
            const rate2 = expansion2.divide(end2 - start2);

            return ee.Dictionary({
                'rate1': rate1,
                'rate2': rate2,
                'area_start1': area_start1,
                'area_end1': area_end1,
                'area_start2': area_start2,
                'area_end2': area_end2,
                'valid': 1
            });
        },
        () => ee.Dictionary({'valid': 0})
    );

    const resultsDict = await ee.data.computeValue(result);

    // 4. Validation & Final Answer
    if (resultsDict.valid === 0) {
        console.log("Evidence: Could not find imagery for one or more years in the specified ranges.");
        console.log("A: No");
        return;
    }

    // Convert area from sq meters to million sq km for readability
    const M_SQ_KM_CONV = 1e-12;
    console.log(`Cropland Area ${start1} (M km^2): ${(resultsDict.area_start1 * M_SQ_KM_CONV).toFixed(2)}`);
    console.log(`Cropland Area ${end1} (M km^2): ${(resultsDict.area_end1 * M_SQ_KM_CONV).toFixed(2)}`);
    console.log(`Cropland Area ${start2} (M km^2): ${(resultsDict.area_start2 * M_SQ_KM_CONV).toFixed(2)}`);
    console.log(`Cropland Area ${end2} (M km^2): ${(resultsDict.area_end2 * M_SQ_KM_CONV).toFixed(2)}`);

    const rate1_val = resultsDict.rate1 * M_SQ_KM_CONV;
    const rate2_val = resultsDict.rate2 * M_SQ_KM_CONV;

    if (rate1_val === null || rate2_val === null || isNaN(rate1_val) || isNaN(rate2_val)) {
        console.log("Evidence: Calculation resulted in a null or NaN value.");
        console.log("C3: Calculation Failure");
        return;
    }

    console.log(`Expansion Rate ${start1}-${end1} (M km^2/year): ${rate1_val.toFixed(4)}`);
    console.log(`Expansion Rate ${start2}-${end2} (M km^2/year): ${rate2_val.toFixed(4)}`);

    if (rate2_val < rate1_val) {
        console.log("Evidence: The expansion rate in 2016-2019 was slower than in 2004-2007.");
        console.log("A: Yes");
    } else {
        console.log("Evidence: The expansion rate in 2016-2019 was not slower than in 2004-2007.");
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during Earth Engine initialization or analysis.");
        console.error(e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
